# FLASK
#
# Define common prefixes for access vectors
#
# common common_name { permission_name ... }


#
# Define a common prefix for file access vectors.
#

common file
{
        ioctl
        read
        write
        create
        getattr
        setattr
        lock
        relabelfrom
        relabelto
        append
        unlink
        link
        rename
        execute
        swapon
        quotaon
        mounton
}


#
# Define a common prefix for socket access vectors.
#

common socket
{
# inherited from file
        ioctl
        read
        write
        create
        getattr
        setattr
        lock
        relabelfrom
        relabelto
        append
# socket-specific
        bind
        connect
        listen
        accept
        getopt
        setopt
        shutdown
        recvfrom
        sendto
        recv_msg
        send_msg
        name_bind
}

#
# Define a common prefix for ipc access vectors.
#

common ipc
{
        create
        destroy
        getattr
        setattr
        read
        write
        associate
        unix_read
        unix_write
}

#
# Define the access vectors.
#
# class class_name [ inherits common_name ] { permission_name ... }


#
# Define the access vector interpretation for file-related objects.
#

class filesystem
{
        mount
        remount
        unmount
        getattr
        relabelfrom
        relabelto
        transition
        associate
        quotamod
        quotaget
}

class dir
inherits file
{
        add_name
        remove_name
        reparent
        search
        rmdir
}

class file
inherits file
{
        execute_no_trans
        entrypoint
}

class lnk_file
inherits file

class chr_file
inherits file

class blk_file
inherits file

class sock_file
inherits file

class fifo_file
inherits file

class fd
{
        use
}


#
# Define the access vector interpretation for network-related objects.
#

class socket
inherits socket

class tcp_socket
inherits socket
{
        connectto
        newconn
        acceptfrom
}

class udp_socket
inherits socket

class rawip_socket
inherits socket

